const TITLE_STRONG = ['business analyst','project coordinator','pmo','project assistant','projektkoordinator','projektassistent','project manager','projektmanager'];
const SKILLS = ['sql','jira','agile','scrum','kanban','excel','requirements','anforderung','stakeholder','user stor','uat','power bi','tableau','python','prozess','process','ifrs','sprint','test'];
const FLUENT = ['fluent german','fließend','verhandlungssicher','sehr gute deutschkenntnisse','deutsch c1','deutsch c2','german c1','german (c1','muttersprach'];
const DE_MARKERS = [' und ',' die ',' der ',' wir ',' du ',' sie ','aufgaben','erfahrung','kenntnisse'];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.id) continue;                       // empty placeholder
  if (j.property_pre_score !== null && j.property_pre_score !== undefined) continue; // already scored

  const title = String(j.name || '').toLowerCase();
  const desc = String(j.property_raw_job_description || '').toLowerCase();
  const loc = String(j.property_location || '').toLowerCase();
  const text = title + ' ' + desc;

  // 1. Title (30)
  let t = 0;
  if (TITLE_STRONG.some(k => title.includes(k))) t = 30;
  else if (/analyst|project|projekt|pmo/.test(title)) t = 20;

  // 2. Skills (25): 6 matches = full points
  const matched = SKILLS.filter(k => text.includes(k));
  const s = Math.min(25, Math.round(25 * matched.length / 6));

  // 3. Location / remote (15)
  let l = 0;
  if (/remote/.test(text)) l = 15;
  else if (loc.includes('berlin')) l = 12;
  else if (/hybrid|home ?office|mobiles arbeiten/.test(text)) l = 8;

  // 4. Contact (15)
  const c = (j.property_contacts || []).length > 0 ? 15 : 0;

  // 5. German (10)
  let german = 'None', g = 10;
  if (FLUENT.some(k => text.includes(k))) { german = 'Fluent'; g = 0; }
  else if (DE_MARKERS.filter(k => text.includes(k)).length >= 3) { german = 'Basic'; g = 5; }

  // 6. Seniority (5)
  let r = 3;
  if (/senior|lead|head|principal|leiter/.test(title)) r = -15;
  else if (/junior|entry|trainee|werkstudent|associate/.test(title)) r = 5;

  const total = t + s + l + c + g + r;
  out.push({ json: {
    job_id: j.id,
    pre_score: total,
    breakdown: `Title ${t}, Skills ${s}, Location ${l}, Contact ${c}, German ${g} (${german}), Seniority ${r}`,
    matched_skills: matched.join(', '),
    german_required: german
  }});
}
return out;
